import { useEffect, useState } from "react";

function Attendance() {
  const [students, setStudents] = useState([]);
  const [selectedClass, setSelectedClass] = useState("");
  const [attendance, setAttendance] = useState({}); // { studentId: "Present"/"Absent" }

  useEffect(() => {
    const allStudents = JSON.parse(localStorage.getItem("students")) || [];
    setStudents(allStudents);
    const savedAttendance = JSON.parse(localStorage.getItem("attendance")) || {};
    setAttendance(savedAttendance);
  }, []);

  // Get unique class list
  const classes = [...new Set(students.map(s => s.class))];

  const handleMark = (studentId, status) => {
    const updated = { ...attendance, [studentId]: status };
    setAttendance(updated);
    localStorage.setItem("attendance", JSON.stringify(updated));
  };

  const handleDeleteAttendance = (studentId) => {
    const updated = { ...attendance };
    delete updated[studentId];
    setAttendance(updated);
    localStorage.setItem("attendance", JSON.stringify(updated));
  };

  // Filter students by selected class
  const classStudents = students.filter(s => s.class === selectedClass);

  return (
    <div style={{ padding: "20px" }}>
      <h2>Attendance</h2>

      <div>
        <label>Select Class: </label>
        <select value={selectedClass} onChange={e => setSelectedClass(e.target.value)}>
          <option value="">--Select Class--</option>
          {classes.map(cls => (
            <option key={cls} value={cls}>{cls}</option>
          ))}
        </select>
      </div>

      {selectedClass && classStudents.length === 0 && <p>No students in this class.</p>}

      {selectedClass && classStudents.length > 0 && (
        <table border="1" cellPadding="8" style={{ marginTop: "10px", borderCollapse: "collapse" }}>
          <thead>
            <tr>
              <th>Name</th>
              <th>Roll</th>
              <th>Attendance</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {classStudents.map(student => (
              <tr key={student.id}>
                <td>{student.name}</td>
                <td>{student.roll}</td>
                <td>
                  <select
                    value={attendance[student.id] || ""}
                    onChange={e => handleMark(student.id, e.target.value)}
                  >
                    <option value="">--Mark--</option>
                    <option value="Present">Present</option>
                    <option value="Absent">Absent</option>
                  </select>
                </td>
                <td>
                  <button onClick={() => handleDeleteAttendance(student.id)} style={{ background: "red", color: "white", border: "none", cursor: "pointer" }}>
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

export default Attendance;
